{
  "tool": "evaluate",
  "args": {
    "name": "biases_thrusters_main",
    "hypothesis": "Increase the biases for side thrusters (actions 1 and 3) and the main engine (action 2) while slightly discouraging the off action. This should make the policy fire side thrusters more often to counter strong wind and fire the main engine more often to counter weaker thrust and stronger gravity, improving landing success under the compound physics.",
    "ops": [
      {
        "op": "set",
        "edits": [
          { "tensor": "b3", "index": [0], "value": -0.05 },
          { "tensor": "b3", "index": [1], "value": 0.2 },
          { "tensor": "b3", "index": [2], "value": 0.5 },
          { "tensor": "b3", "index": [3], "value": 0.2 }
        ]
      }
    ]
  }
}

{
  "tool": "evaluate",
  "args": {
    "name": "biases_thrusters_main_offset",
    "hypothesis": "Increase the biases for side thrusters (actions 1 and 3) and the main engine (action 2) while slightly discouraging the off action, and shift the observation inputs to make the policy think it is higher, descending faster, and moving horizontally faster. This should cause earlier and more frequent side and main thrust, countering strong wind and weaker main engine under the compound physics, improving landing success.",
    "ops": [
      {
        "op": "set",
        "edits": [
          { "tensor": "b3", "index": [0], "value": -0.2 },
          { "tensor": "b3", "index": [1], "value": 0.5 },
          { "tensor": "b3", "index": [2], "value": 1.0 },
          { "tensor": "b3", "index": [3], "value": 0.5 }
        ]
      },
      {
        "op": "input_affine",
        "offset": [0, 0.2, 0.2, -0.05, 0, 0.2, 0, 0]
      }
    ]
  }
}

{
  "tool": "evaluate",
  "args": {
    "name": "input_scale_x_hv_av_bias_main",
    "hypothesis": "Increase the influence of horizontal position, horizontal velocity, and angular velocity in the observation (scale them up) so the policy reacts earlier to wind and attitude errors, and set the output biases to strongly favor side thrusters and especially the main engine while discouraging the off action. This should cause more frequent side thrust to counter strong wind and more aggressive main thrust to counter weaker engine and stronger gravity, improving landing success under the compound physics.",
    "ops": [
      {
        "op": "input_affine",
        "scale": [2.0, 1.0, 2.0, 1.2, 1.0, 2.0, 1.0, 1.0]
      },
      {
        "op": "set",
        "edits": [
          { "tensor": "b3", "index": [0], "value": -0.5 },
          { "tensor": "b3", "index": [1], "value": 0.5 },
          { "tensor": "b3", "index": [2], "value": 1.5 },
          { "tensor": "b3", "index": [3], "value": 0.5 }
        ]
      }
    ]
  }
}
